head.script:
///////// 1. 변수 및 선언 영역 /////////
// 공동공시 조회

scwin.arrMKT = [9, 1, 2, 6];
scwin.arrFORM = [1, 2, 3, 4];

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        scwin.setCode();
        scwin.init();

        // 패널라운드 처리
        $c.cm.PanelToGroupBox(panel_1);
        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF10960.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {void}
 * @hidden N
 */
scwin.init = function() {
    checkbox_MKT0.setValue(1);
    for (let i = 0; i < scwin.arrMKT.length; i++) {
        $p.getComponentById("checkbox_MKT" + scwin.arrMKT[i]).setValue(1);
    }
    panel_MKT1.style.visibility = "";
    panel_MKT2.style.visibility = "";
    panel_MKT6.style.visibility = "";
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name dts_DisclsForm_OnLoadError
 * @description dts_DisclsForm 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_DisclsForm_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_DisclsForm);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF10960.dts_DisclsForm_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_DisclsForm_OnLoadCompleted
 * @description dts_DisclsForm 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_DisclsForm_OnLoadCompleted = async function(rowcount) {
    try {
        if (dts_DisclsForm.errorMsg) {
            await $c.win.alert(dts_DisclsForm.errorMsg);
        } else {
            $c.stf.fillGridHeaderTotalCnt(rowcount, panel_page);
        }
        btn_Search.setDisabled(false);
        btn_Search.src = "../img/btn_select.gif";
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF10960.dts_DisclsForm_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name btn_Search_onclick
 * @description btn_Search 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function() {
    try {
        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF10960.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name btn_Excel_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Excel_onclick = function() {
    try {
        $c.stf.doLogSave('ULDSTF10960.xml', SCREN_PROCS_TP_CD_07, '');
        const file_name = "공동공시조회";
        const today = $c.ut.cGetToday('yyyymmddhhmmss');
        const xls_path = $c.session.getExcelDownPath() + today + "_" + file_name + ".xlsx";
        $c.data.downloadGridViewOffice(grd_DisclsForm, file_name, xls_path, "8", 0);
        // grd_DisclsForm.GridToExcel("공동공시조회", "", "8");
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF10960.btn_Excel_onclick" });
    }
};

/**
 * @method
 * @name checkbox_FORM0_onclick
