///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name search
 * @description search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function() {
    if (!await scwin.validCheck()) return;
    btn_Search.setDisabled(true);
    btn_Search.src = "../img/btn_select_d.gif";
    const sbmOptions = {
        id : "sbm_dts_DisclsForm",
        action : "/MktActNotice.do",
        ref : "",
        target : "dts_DisclsForm=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name setCode
 * @description 현재날짜 셋팅
 * @returns {void}
 * @hidden N
 */
scwin.setCode = function() {
    // 현재날짜 셋팅
    edt_SrchDay.setValue($c.ut.cGetToday("yyyymmdd"));
};

/**
 * @method
 * @name getCheckedMKT
 * @description get Checked MKT 처리
 * @returns {void}
 * @hidden N
 */
scwin.getCheckedMKT = function() {
    let text = "";
    for (let i = 0; i < scwin.arrMKT.length; i++) {
        if ($p.getComponentById("checkbox_MKT" + scwin.arrMKT[i]).checked) {
            text.setValue(text.getValue() + scwin.arrMKT[i] + ",");
        }
    }
    return text;
};

/**
 * @method
 * @name getCheckedFORM
 * @description get Checked FORM 처리
 * @returns {void}
 * @hidden N
 */
scwin.getCheckedFORM = function() {
    let text = "";
    for (let i = 0; i < scwin.arrFORM.length; i++) {
        if ($p.getComponentById("checkbox_FORM" + scwin.arrFORM[i]).checked) {
            text.setValue(text.getValue() + scwin.arrFORM[i] + ",");
        }
    }
    return text;
};

/**
 * @method
 * @name validCheck
 * @description valid Check 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.validCheck = async function() {
    let a = 0;
    for (let i = 0; i < scwin.arrMKT.length; i++) {
        if ($p.getComponentById("checkbox_MKT" + scwin.arrMKT[i]).checked) {
            a++;
        }
    }
    if (a === 0) {
        await $c.win.alert("시장구분을 선택해 주세요.");
        checkbox_MKT0.focus();
        return false;
    }
    return true;
};

/**
 * @method
 * @name checkboxFORM
 * @description checkbox FORM 처리
 * @param {String} flag flag
 * @returns {void}
 * @hidden N
 */
scwin.checkboxFORM = function(flag) {
    if (flag === "0") {
        // 전체
        if (checkbox_FORM0.checked) {
            for (let i = 0; i < scwin.arrFORM.length; i++) {
                $p.getComponentById("checkbox_FORM" + scwin.arrFORM[i]).setValue(1);
            }
        } else {
            for (let i = 0; i < scwin.arrFORM.length; i++) {
                $p.getComponentById("checkbox_FORM" + scwin.arrFORM[i]).setValue(0);
            }
        }
    } else {
        let a = 0;
        for (let i = 0; i < scwin.arrFORM.length; i++) {
            if (!$p.getComponentById("checkbox_FORM" + scwin.arrFORM[i]).checked) {
                a++;
            }
        }
        if (a === 0) {
            checkbox_FORM0.setValue(1);
        } else {
            checkbox_FORM0.setValue(0);
        }
    }
};

/**
 * @method
 * @name checkboxMKT
 * @description checkbox MKT 처리
 * @param {String} flag flag
 * @returns {void}
 * @hidden N
 */
scwin.checkboxMKT = function(flag) {
    if (flag === "0") {
        // 전체
        if (checkbox_MKT0.checked) {
            for (let i = 0; i < scwin.arrMKT.length; i++) {
                $p.getComponentById("checkbox_MKT" + scwin.arrMKT[i]).setValue(1);
            }
        } else {
            for (let i = 0; i < scwin.arrMKT.length; i++) {
                $p.getComponentById("checkbox_MKT" + scwin.arrMKT[i]).setValue(0);
            }
        }
    } else {
        let a = 0;
        for (let i = 0; i < scwin.arrMKT.length; i++) {
            if (!$p.getComponentById("checkbox_MKT" + scwin.arrMKT[i]).checked) {
                a++;
            }
        }
        if (a === 0) {
            checkbox_MKT0.setValue(1);
        } else {
            checkbox_MKT0.setValue(0);
        }
    }
};
